#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>

#define CYAN  "\033[36m"
#define BOLD  "\033[1m"
#define END   "\033[0m"
#define RED   "\033[31m"

static const char *pos;
static int had_error;

static double parse_expr(void);

static void skip_ws(void) {
    while (*pos == ' ' || *pos == '\t') pos++;
}

static double parse_number(void) {
    skip_ws();
    if (*pos == '(') {
        pos++;
        double v = parse_expr();
        skip_ws();
        if (*pos == ')') pos++;
        else { fprintf(stderr, RED "error: missing ')'" END "\n"); had_error = 1; }
        return v;
    }
    if (*pos == '-') { pos++; return -parse_number(); }
    if (*pos == '+') { pos++; return  parse_number(); }

    if (!isdigit((unsigned char)*pos) && *pos != '.') {
        fprintf(stderr, RED "error: unexpected '%c'" END "\n", *pos ? *pos : '?');
        had_error = 1;
        return 0;
    }
    char *end;
    double v = strtod(pos, &end);
    pos = end;
    return v;
}

static double parse_term(void) {
    double left = parse_number();
    for (;;) {
        skip_ws();
        char op = *pos;
        if (op != '*' && op != '/' && op != '%') break;
        pos++;
        double right = parse_number();
        if (op == '*') left *= right;
        else if (op == '/') {
            if (right == 0) { fprintf(stderr, RED "error: division by zero" END "\n"); had_error = 1; return 0; }
            left /= right;
        } else {
            left = fmod(left, right);
        }
    }
    return left;
}

static double parse_expr(void) {
    double left = parse_term();
    for (;;) {
        skip_ws();
        char op = *pos;
        if (op != '+' && op != '-') break;
        pos++;
        double right = parse_term();
        left = (op == '+') ? left + right : left - right;
    }
    return left;
}

static void evaluate(const char *line) {
    pos = line;
    had_error = 0;
    skip_ws();
    if (!*pos) return;

    double result = parse_expr();
    skip_ws();
    if (*pos && !had_error) {
        fprintf(stderr, RED "error: unexpected '%c'" END "\n", *pos);
        return;
    }
    if (had_error) return;

    /* print as integer if it's a whole number */
    if (result == (long long)result && result >= -1e15 && result <= 1e15)
        printf(CYAN "= %lld" END "\n", (long long)result);
    else
        printf(CYAN "= %g" END "\n", result);
}

int main(void) {
    char line[256];
    int interactive = 1;

    printf(BOLD "calc" END " — type an expression, 'q' to quit\n");

    while (1) {
        if (interactive) printf(BOLD "> " END);
        if (!fgets(line, sizeof(line), stdin)) break;

        /* strip newline */
        line[strcspn(line, "\r\n")] = '\0';

        if (!line[0]) continue;
        if (!strcmp(line, "q") || !strcmp(line, "quit") || !strcmp(line, "exit")) break;

        evaluate(line);
    }
    return 0;
}
